`timescale 1ns/1ps
// Golden-reference TB: drive the raw recovered iCE40 netlist like the RP2040
// MicroPython controller does, and check the known test vector.
//
// Pin hypothesis (from fanout + structural analysis):
//   SCK=io_9_31_1  RST_N=io_19_31_1  NORM_CS_N=io_17_31_0  MOSI=io_16_31_0
//   ENC_DEC=io_13_31_1  START=io_18_31_1
//   BUSY=io_8_31_1  ICE_LED=io_19_31_0  MISO=io_16_31_1

module tb;
  reg SCK=0, RST_N=1, NORM_CS_N=1, MOSI=0, ENC_DEC=0, START=0;
  wire BUSY, ICE_LED, MISO;

  chip dut(
    .io_9_31_1(SCK), .io_19_31_1(RST_N), .io_17_31_0(NORM_CS_N),
    .io_16_31_0(MOSI), .io_13_31_1(ENC_DEC), .io_18_31_1(START),
    .io_8_31_1(BUSY), .io_19_31_0(ICE_LED), .io_16_31_1(MISO)
  );

  // one SCK period
  task tick; begin #10 SCK=1; #10 SCK=0; end endtask

  // shift one byte in on MOSI, MSB first, sampling MISO before each rising edge
  task xfer_byte(input [7:0] tx, output [7:0] rx);
    integer i;
    begin
      for (i=7;i>=0;i=i-1) begin
        MOSI = tx[i];
        #5;                 // setup while SCK low
        rx[i] = MISO;       // controller samples (value held from before edge)
        #5 SCK=1; #10 SCK=0;
      end
    end
  endtask

  task do_reset; begin
    RST_N=0; tick; RST_N=1; tick;
  end endtask

  integer k;
  reg [7:0] r0,r1,r2,r3;
  reg [31:0] result;

  initial begin
    $dumpfile("tb_netlist.vcd"); $dumpvars(0,tb);
    SCK=0; RST_N=1; NORM_CS_N=1; START=0; ENC_DEC=0; MOSI=0;
    tick;
    do_reset;

    // ---- ENCRYPT path ----
    ENC_DEC=0;
    // ingest 0x59 C3 59 C3, MSB-first, byte0 first
    NORM_CS_N=0;
    xfer_byte(8'h59,r0); xfer_byte(8'hC3,r1);
    xfer_byte(8'h59,r2); xfer_byte(8'hC3,r3);
    NORM_CS_N=1;

    // START pulse
    START=1; tick; START=0;
    $display("after start: BUSY=%b", BUSY);

    // run clocks until BUSY falls (cap at 20)
    for (k=0;k<20 && BUSY;k=k+1) tick;
    $display("BUSY fell after extra clocks; BUSY=%b", BUSY);
    tick; // settle / parallel load

    // extract 32 bits
    NORM_CS_N=0;
    xfer_byte(8'h00,r0); xfer_byte(8'h00,r1);
    xfer_byte(8'h00,r2); xfer_byte(8'h00,r3);
    NORM_CS_N=1;
    result = {r0,r1,r2,r3};
    $display("ENCRYPT result = %02x %02x %02x %02x  (expect 9C D8 43 92)", r0,r1,r2,r3);
    if (result===32'h9CD84392) $display("*** ENCRYPT MATCH ***");
    else $display("    encrypt mismatch (got %08x)", result);

    $finish;
  end

  // safety timeout
  initial begin #200000 $display("TIMEOUT"); $finish; end
endmodule

