// Brute-force pins with BUSY-driven waiting + sliding-window readout match.
module tb;
  reg [5:0] phys = 0;
  wire BUSY, ICE_LED, MISO;
  chip dut(
    .io_9_31_1(phys[0]), .io_19_31_1(phys[1]), .io_17_31_0(phys[2]),
    .io_16_31_0(phys[3]), .io_13_31_1(phys[4]), .io_18_31_1(phys[5]),
    .io_8_31_1(BUSY), .io_19_31_0(ICE_LED), .io_16_31_1(MISO)
  );
  integer P_RST,P_CS,P_MOSI,P_START,P_ENC;
  task tick; begin phys[0]=1; #10; phys[0]=0; #10; end endtask

  reg [63:0] stream;
  integer busyclocks;

  task run_trial;
    integer i;
    begin
      phys[1]=0;phys[2]=0;phys[3]=0;phys[4]=0;phys[5]=0; tick; tick;
      phys[P_RST]=1; phys[P_CS]=1; phys[P_START]=0; phys[P_ENC]=0; tick;
      phys[P_RST]=0; tick; phys[P_RST]=1; tick;
      phys[P_ENC]=0;
      // ingest
      phys[P_CS]=0;
      for (i=31;i>=0;i=i-1) begin phys[P_MOSI]=(32'h59C359C3>>i)&1; #10; tick; end
      phys[P_CS]=1; tick;
      // start
      phys[P_START]=1; tick; phys[P_START]=0;
      // wait for BUSY to fall
      busyclocks=0;
      for (i=0;i<16 && BUSY;i=i+1) begin tick; busyclocks=busyclocks+1; end
      tick;
      // read 64 bits MSB-first, sample before each edge
      phys[P_CS]=0; stream=0;
      for (i=0;i<64;i=i+1) begin
        phys[P_MOSI]=0; #5; stream={stream[62:0],MISO}; #5; tick;
      end
      phys[P_CS]=1;
    end
  endtask

  // slide 32-bit window across the 64-bit stream, look for target
  function integer find_target(input [63:0] s, input [31:0] tgt);
    integer off; reg found;
    begin
      find_target=-1;
      for (off=0; off<=32; off=off+1)
        if (((s>>off)&32'hFFFFFFFF)===tgt) find_target=off;
    end
  endfunction

  integer a,b,c,d,e,off,nf;
  initial begin
    nf=0;
    for (a=1;a<=5;a=a+1)
    for (b=1;b<=5;b=b+1) if(b!=a)
    for (c=1;c<=5;c=c+1) if(c!=a&&c!=b)
    for (d=1;d<=5;d=d+1) if(d!=a&&d!=b&&d!=c)
    for (e=1;e<=5;e=e+1) if(e!=a&&e!=b&&e!=c&&e!=d) begin
      P_RST=a;P_CS=b;P_MOSI=c;P_START=d;P_ENC=e;
      run_trial;
      off=find_target(stream,32'h9CD84392);
      if (off>=0) begin
        $display("*** MATCH *** RST=%0d CS=%0d MOSI=%0d START=%0d ENC=%0d | off=%0d busyclks=%0d stream=%016x",
                 a,b,c,d,e,off,busyclocks,stream);
        nf=nf+1;
      end
    end
    $display("done matches=%0d",nf);
    $finish;
  end
  initial begin #200000000 $display("TIMEOUT"); $finish; end
endmodule

