        if(((st>>o)&32'hFFFFFFFF)===rev32(t)) $display("   %0s revbit @%0d",nm,o);
        if(((st>>o)&32'hFFFFFFFF)===bswap(t)) $display("   %0s byteswap @%0d",nm,o);
      end
