// first. Read 72 bits, scan target in normal/revbit/byteswap at all offsets.
module tb;
  reg [5:0] phys=0;
  wire BUSY,ICE_LED,MISO;
  chip dut(.io_9_31_1(phys[0]),.io_19_31_1(phys[1]),.io_17_31_0(phys[2]),
    .io_16_31_0(phys[3]),.io_13_31_1(phys[4]),.io_18_31_1(phys[5]),
    .io_8_31_1(BUSY),.io_19_31_0(ICE_LED),.io_16_31_1(MISO));
  integer P_RST,P_CS,P_MOSI,P_START,P_ENC,ORD;
  task tick; begin phys[0]=1;#10;phys[0]=0;#10; end endtask
  reg [71:0] s; integer busyc;
  function [31:0] rev32(input[31:0] x); integer i; begin
    for(i=0;i<32;i=i+1) rev32[i]=x[31-i]; end endfunction
  function [31:0] bswap(input[31:0] x); begin
    bswap={x[7:0],x[15:8],x[23:16],x[31:24]}; end endfunction
  function integer scan1(input[71:0] st,input[31:0] t); integer o; begin
    scan1=-99;
    for(o=0;o<=40;o=o+1) begin
      if(((st>>o)&32'hFFFFFFFF)===t) scan1=o;
      else if(((st>>o)&32'hFFFFFFFF)===rev32(t)) scan1=100+o;
      else if(((st>>o)&32'hFFFFFFFF)===bswap(t)) scan1=200+o;
    end end endfunction

  task runvec(input e,input[31:0] din);
    integer i; begin
      phys[1]=0;phys[2]=0;phys[3]=0;phys[4]=0;phys[5]=0; tick;tick;
      phys[P_RST]=0; phys[P_CS]=1; phys[P_START]=0; phys[P_ENC]=e; tick;
      phys[P_RST]=1; tick;
      phys[P_CS]=0;
      for(i=0;i<32;i=i+1) begin phys[P_MOSI]=(ORD==0)?(din>>(31-i))&1:(din>>i)&1; #10; tick; end
      phys[P_CS]=1; tick;
      phys[P_START]=1; tick; phys[P_START]=0;
      busyc=0; while(BUSY && busyc<16) begin tick; busyc=busyc+1; end
      phys[P_CS]=0; s=0;
      for(i=0;i<72;i=i+1) begin phys[P_MOSI]=0;#5; s={s[70:0],MISO};#5; tick; end
      phys[P_CS]=1;
    end
  endtask

  integer a,b,c,d,e,hit,nf;
  initial begin
    nf=0;
    for(ORD=0;ORD<=1;ORD=ORD+1)
