    for(c=1;c<=5;c=c+1) if(c!=a&&c!=b)
    for(d=1;d<=5;d=d+1) if(d!=a&&d!=b&&d!=c)
    for(e=1;e<=5;e=e+1) if(e!=a&&e!=b&&e!=c&&e!=d) begin
      P_RST=a;P_CS=b;P_MOSI=c;P_START=d;P_ENC=e;
      runvec(1'b0,32'h59C359C3);
      hit=scan1(s,32'h9CD84392);
      if(hit!=-99) begin
        $display("*** HIT ord=%0d RST=%0d CS=%0d MOSI=%0d START=%0d ENC=%0d busyc=%0d code=%0d s=%018x",
                 ORD,a,b,c,d,e,busyc,hit,s);
        nf=nf+1;
      end
    end
    $display("done hits=%0d",nf);
    $finish;
  end
  initial begin #600000000 $display("TIMEOUT"); $finish; end
endmodule

