`timescale 1ns/1ps
// Faithful replica of spi_ice40_crypto_ip_test.py main(), using the confirmed
// pin map. SoftSPI mode 0 (CPOL=0,CPHA=0), MSB-first, 8-bit.
module tb;
  reg [5:0] phys=0;
  wire BUSY,ICE_LED,MISO;
  chip dut(.io_9_31_1(phys[0]),.io_19_31_1(phys[1]),.io_17_31_0(phys[2]),
    .io_16_31_0(phys[3]),.io_13_31_1(phys[4]),.io_18_31_1(phys[5]),
    .io_8_31_1(BUSY),.io_19_31_0(ICE_LED),.io_16_31_1(MISO));
  // SCK=io_9_31_1, RST_N=io_13_31_1, NORM_CS_N=io_17_31_0, MOSI=io_16_31_0,
  // ENC_DEC=io_19_31_1, START=io_18_31_1
  `define SCK   phys[0]
  `define RSTN  phys[4]
  `define CSN   phys[2]
  `define MOSI  phys[3]
  `define ENC   phys[1]
  `define START phys[5]

  task sck_pulse; begin `SCK=1; #10; `SCK=0; #10; end endtask

  // SoftSPI write one byte, MSB first
  task spi_write(input [7:0] b);
    integer i; begin
      for(i=7;i>=0;i=i-1) begin `MOSI=b[i]; #5; `SCK=1; #10; `SCK=0; #5; end
    end
  endtask
  // SoftSPI write_readinto one byte: sample MISO just before rising edge
  task spi_wri(input [7:0] tx, output [7:0] rx);
    integer i; begin
      for(i=7;i>=0;i=i-1) begin `MOSI=tx[i]; #5; rx[i]=MISO; `SCK=1; #10; `SCK=0; #5; end
    end
  endtask

  reg [7:0] r0,r1,r2,r3;
  task rd4(input[7:0]a,b,c,d); begin end endtask

  initial begin
    $dumpfile("mpy.vcd"); $dumpvars(0,tb);
    `SCK=0; `RSTN=1; `CSN=1; `START=0; `ENC=0; `MOSI=0; #20;

    // reset the core
    `RSTN=0; sck_pulse; `RSTN=1; sck_pulse;

    // --- SPI readback test: write plaintext, then write_readinto ---
    `CSN=0; spi_write(8'h59); spi_write(8'hC3); spi_write(8'h59); spi_write(8'hC3); `CSN=1;
    `CSN=0; spi_wri(8'h59,r0); spi_wri(8'hC3,r1); spi_wri(8'h59,r2); spi_wri(8'hC3,r3); `CSN=1;
    $display("SPI readback: %02x %02x %02x %02x (expect 59 C3 59 C3)",r0,r1,r2,r3);

    // --- Encryption test (NO reset first, per MicroPython) ---
    `ENC=0;
    `START=1; sck_pulse; `START=0;
    $display("after start: BUSY=%b (expect 1)",BUSY);
    repeat(7) sck_pulse;
    $display("after 7 clocks: BUSY=%b (expect 0)",BUSY);
    `CSN=0; spi_wri(8'h59,r0); spi_wri(8'hC3,r1); spi_wri(8'h59,r2); spi_wri(8'hC3,r3); `CSN=1;
    $display("ENCRYPT result: %02x %02x %02x %02x (expect 9C D8 43 92)",r0,r1,r2,r3);

    // --- Decryption test (reset first) ---
    `ENC=1;
    `RSTN=0; sck_pulse; `RSTN=1; sck_pulse;
    `CSN=0; spi_write(8'h9C); spi_write(8'hD8); spi_write(8'h43); spi_write(8'h92); `CSN=1;
    `START=1; sck_pulse; `START=0;
    repeat(7) sck_pulse;
    `CSN=0; spi_wri(8'h9C,r0); spi_wri(8'hD8,r1); spi_wri(8'h43,r2); spi_wri(8'h92,r3); `CSN=1;
    $display("DECRYPT result: %02x %02x %02x %02x (expect 59 C3 59 C3)",r0,r1,r2,r3);
    $finish;
  end
  initial begin #30000000 $finish; end
endmodule

