# Find FFs that (a) differ across inputs I00/I01/IFF/I5A at some cycle => input-byte0 dependent crypto state
def parse(fn):
    out=[]
    for line in open(fn):
        line=line.strip()
        if ':' not in line: continue
        head,rest=line.split(':',1)
        d={}
        for tok in rest.split():
